    correctOptionId: 'b',
    explanation: "Allophones are non-contrastive phonetic realizations of a phoneme. In English, voiceless stops are aspirated in syllable-initial position ([pʰɪn]), but unaspirated after /s/ ([spɪn]). Because substituting [p] for [pʰ] sounds unnatural but does not change the word's meaning, they are allophones.",
